1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { Button as ChakraButton } from '@salesforce/retail-react-app/app/components/shared/ui';
4	
5	const ZIMM_SOCIAL_BUTTON_RECIPE = 'ZimmSocialButton';
6	
7	export type ZimmSocialButtonProps = {
8	  icon: React.ReactNode;
9	  label: string;
10	  onClick: () => void;
11	  isDisabled?: boolean;
12	};
13	
14	/**
15	 * Full-width outlined button for social identity providers (Apple, Google).
16	 * Renders an icon alongside uppercase label text, matching the auth drawer
17	 * Figma spec (variant "secondary outline" with leading icon slot).
18	 *
19	 * Root visual states (hover, press, focus, disabled) come from zimmButton.css.ts's
20	 * `social` variant — sub-element sizing and alignment live in ZimmSocialButton's own recipe.
21	 * ChakraButton is used directly so the component fully owns its DOM structure without
22	 * depending on ZimmButton's iconLeading slot rendering.
23	 */
24	export const ZimmSocialButton = ({ icon, label, onClick, isDisabled = false }: ZimmSocialButtonProps) => {
25	  const styles = useMultiStyleConfig(ZIMM_SOCIAL_BUTTON_RECIPE, {});
26	
27	  return (
28	    <ChakraButton
29	      type="button"
30	      variant="social"
31	      size="social"
32	      width="100%"
33	      isDisabled={isDisabled}
34	      onClick={onClick}
35	    >
36	      <chakra.span __css={styles.container}>
37	        <chakra.span aria-hidden={true} __css={styles.icon}>{icon}</chakra.span>
38	        <chakra.span __css={styles.label}>{label}</chakra.span>
39	      </chakra.span>
40	    </ChakraButton>
41	  );
42	};
