1	import React, { ErrorInfo } from 'react';
2	
3	type ErrorFallbackState = { hasError: boolean };
4	
5	/** Error boundary for ZimmAuthDrawerContent — class component required by React's error boundary API. */
6	export class ErrorFallback extends React.Component<React.PropsWithChildren, ErrorFallbackState> {
7	  constructor(props: React.PropsWithChildren) {
8	    super(props);
9	    this.state = { hasError: false };
10	  }
11	
12	  static getDerivedStateFromError(): ErrorFallbackState {
13	    return { hasError: true };
14	  }
15	
16	  componentDidCatch(error: Error, info: ErrorInfo): void {
17	    // console.error is permitted inside error boundaries per conventions.md
18	    console.error('[ZimmAuthDrawerContent] render error', error, info.componentStack);
19	  }
20	
21	  render(): React.ReactNode {
22	    if (this.state.hasError) {
23	      // Intentionally blank — if any auth sub-component crashes (email/OTP input, social
24	      // buttons, create-account panel) the drawer shows empty rather than a broken UI.
25	      // A Zimmermann-designed error state can replace this null once confirmed.
26	      return null;
27	    }
28	    return this.props.children;
29	  }
30	}
