2	/**
3	 * One-off seed script — creates the 8 uiCopy entries for the login drawer (SFCC-742).
4	 *
5	 * Usage:
6	 *   node scripts/contentful/seedLoginDrawerUiCopy.mjs --target dev
7	 *
8	 * Targets a single Contentful environment. Defaults to 'dev' if --target is omitted.
9	 * Skips any entry whose key already exists in the target environment (safe to re-run).
10	 * Entries are created AND published in one pass.
11	 *
12	 * Required env vars (from .env via `npm run env -- init`):
13	 *   CONTENTFUL_MANAGEMENT_TOKEN
14	 *   CONTENTFUL_SPACE_ID
15	 */
16	
17	import { checkEnv, createClient, log } from './setup/_shared.mjs';
18	
19	const args = process.argv.slice(2);
20	const getArg = (flag) => {
21	  const i = args.indexOf(flag);
22	  return i !== -1 ? args[i + 1] : null;
23	};
24	
25	const rawTarget = getArg('--target');
26	if (rawTarget === undefined) {
27	  // --target flag was present but no value followed it
28	  console.error('Error: --target requires a value, e.g. --target dev');
29	  process.exit(1);
30	}
31	const TARGET = rawTarget ?? 'dev';
32	
33	checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
34	
35	/** @type {{ key: string; title: string; value: string; description: string }[]} */
36	const ENTRIES = [
37	  {
38	    key: 'login.drawer.email',
39	    title: 'Login Drawer — Email Input Label',
40	    value: 'Email',
41	    description: 'Label for the email address input field in the login drawer.',
42	  },
43	  {
44	    key: 'login.drawer.sendCode',
45	    title: 'Login Drawer — Send Code Button',
46	    value: 'Send code',
47	    description: 'CTA button label that triggers the passwordless email code in the login drawer.',
48	  },
49	  {
50	    key: 'login.drawer.signInWithApple',
51	    title: 'Login Drawer — Sign in with Apple',
52	    value: 'Sign in with Apple',
53	    description: 'Label for the Apple IDP social sign-in button in the login drawer.',
54	  },
55	  {
56	    key: 'login.drawer.signInWithGoogle',
57	    title: 'Login Drawer — Sign in with Google',
58	    value: 'Sign in with Google',
59	    description: 'Label for the Google IDP social sign-in button in the login drawer.',
60	  },
61	  {
62	    key: 'login.drawer.createAccount.heading',
63	    title: 'Login Drawer — Create Account Heading',
64	    value: 'New to Zimmermann?',
65	    description: 'Heading above the create account section at the bottom of the login drawer.',
66	  },
67	  {
68	    key: 'login.drawer.createAccount.body',
69	    title: 'Login Drawer — Create Account Body',
70	    value: 'Join for exclusive offers, early access and a more personal experience.',
71	    description: 'Body copy below the create account heading in the login drawer.',
72	  },
73	  {
74	    key: 'login.drawer.createAccount.cta',
75	    title: 'Login Drawer — Create Account CTA',
76	    value: 'Create an account',
77	    description: 'Button label for the create account action in the login drawer.',
78	  },
79	  {
80	    key: 'login.drawer.wishlist.description',
81	    title: 'Login Drawer — Wishlist Description',
82	    value: 'You must log in or create an account to add items to your wishlist.',
83	    description:
84	      'Descriptive text shown at the top of the login drawer when triggered from a wishlist action.',
85	  },
86	];
87	
88	async function main() {
89	  const client = createClient();
90	
91	  log.section(`Seeding ${ENTRIES.length} uiCopy entries → environment: ${TARGET}`);
92	
93	  // Fetch all existing uiCopy entries across pages before duplicate checks.
94	  // contentful-management paginates at 1,000 — a single request may miss entries.
95	  const existing = [];
96	  let skip = 0;
97	  let total = Infinity;
98	  while (existing.length < total) {
99	    const page = await client.entry.getMany({
100	      environmentId: TARGET,
101	      query: { content_type: 'uiCopy', limit: 1000, skip },
102	    });
103	    total = page.total;
104	    existing.push(...page.items);
105	    skip += page.items.length;
106	    if (page.items.length === 0) break; // guard against a zero-item page to prevent infinite loop
107	  }
108	
109	  // Map from uiCopy key → full entry object so we can inspect sys.publishedVersion below.
110	  const existingEntryMap = new Map(
111	    existing
112	      .map((e) => [e.fields?.key?.['en'], e])
113	      .filter(([key]) => Boolean(key)),
114	  );
115	
116	  let created = 0;
117	  let skipped = 0;
118	  let published = 0;
119	
120	  for (const entry of ENTRIES) {
121	    const existingEntry = existingEntryMap.get(entry.key);
122	    if (existingEntry) {
123	      if (existingEntry.sys.publishedVersion == null) {
124	        // Entry exists as a draft — publish it now so it is available to the app.
125	        await client.entry.publish(
126	          { environmentId: TARGET, entryId: existingEntry.sys.id },
127	          { sys: existingEntry.sys },
128	        );
129	        log.success(`${entry.key} — draft published`);
130	        published++;
131	      } else {
132	        log.skip(`${entry.key} — already published, skipping`);
133	        skipped++;
134	      }
135	      continue;
136	    }
137	
138	    const created_entry = await client.entry.create(
139	      { environmentId: TARGET, contentTypeId: 'uiCopy' },
140	      {
141	        fields: {
142	          title: { 'en': entry.title },
143	          key: { 'en': entry.key },
144	          value: { 'en': entry.value },
145	          description: { 'en': entry.description },
146	        },
147	      },
148	    );
149	
150	    await client.entry.publish(
151	      { environmentId: TARGET, entryId: created_entry.sys.id },
152	      { sys: created_entry.sys },
153	    );
154	
155	    log.success(`${entry.key}`);
156	    created++;
157	  }
158	
159	  log.section('Done');
160	  log.info(`Created and published: ${created}`);
161	  if (published) log.info(`Draft entries published: ${published}`);
162	  if (skipped) log.info(`Skipped (already published): ${skipped}`);
163	}
164	
165	main().catch((err) => {
166	  log.error(err.message ?? String(err));
167	  process.exit(1);
168	});
