1	/**
2	 * Shared utilities for Contentful setup scripts.
3	 * Provides client factory, env validation, and environment polling.
4	 */
5	
6	import { createClient as createCMAClient } from 'contentful-management';
7	
8	export const log = {
9	  info: (msg) => console.log(`  ℹ️  ${msg}`),
10	  success: (msg) => console.log(`  ✅  ${msg}`),
11	  skip: (msg) => console.log(`  ⏭️   ${msg}`),
12	  warn: (msg) => console.warn(`  ⚠️  ${msg}`),
13	  error: (msg) => console.error(`  ❌  ${msg}`),
14	  section: (msg) => console.log(`\n── ${msg} ──`),
15	};
16	
17	/**
18	 * Validates that the required environment variables are set and non-empty.
19	 * Exits the process with a descriptive message if any are missing.
20	 * @param {string[]} required
21	 */
22	export function checkEnv(required) {
23	  const missing = required.filter((k) => !process.env[k]);
24	  if (missing.length) {
25	    log.error(`Missing env vars: ${missing.join(', ')}`);
26	    console.error('   Add them to .env (at repo root) and re-run.\n');
27	    process.exit(1);
28	  }
29	}
30	
31	/**
32	 * Creates a contentful-management plain client scoped to the project space.
33	 * @returns {import('contentful-management').PlainClientAPI}
34	 */
35	export function createClient() {
36	  return createCMAClient(
37	    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
38	    {
39	      type: 'plain',
40	      defaults: { spaceId: process.env.CONTENTFUL_SPACE_ID },
41	    },
42	  );
43	}
44	
45	/**
46	 * Polls an environment until its status is 'ready', then returns it.
47	 * Contentful creates environments asynchronously — this is required after create().
48	 * @param {import('contentful-management').PlainClientAPI} client
49	 * @param {string} environmentId
50	 * @param {number} [timeoutMs=120_000]
51	 * @returns {Promise<object>}
52	 */
53	export async function pollForReady(client, environmentId, timeoutMs = 120_000) {
54	  const deadline = Date.now() + timeoutMs;
55	  while (Date.now() < deadline) {
56	    try {
57	      const env = await client.environment.get({ environmentId });
58	      if (env.sys.status?.sys?.id === 'ready') return env;
59	    } catch (err) {
60	      // 404 immediately after create() is expected — environment is still being provisioned
61	      if (err.status !== 404) throw err;
62	    }
63	    await new Promise((r) => setTimeout(r, 3_000));
64	    process.stdout.write('.');
65	  }
66	  throw new Error(`Environment '${environmentId}' did not become ready within ${timeoutMs / 1000}s`);
67	}
68	
69	/**
70	 * Returns a sorted list of existing environment IDs in the space.
71	 * @param {import('contentful-management').PlainClientAPI} client
72	 * @returns {Promise<string[]>}
73	 */
74	export async function getExistingEnvironmentIds(client) {
75	  const { items } = await client.environment.getMany({ query: { limit: 100 } });
76	  return items.map((e) => e.sys.id);
77	}
78	
79	/**
80	 * Returns existing locale codes in a given environment.
81	 * @param {import('contentful-management').PlainClientAPI} client
82	 * @param {string} environmentId
83	 * @returns {Promise<string[]>}
84	 */
85	export async function getExistingLocaleCodes(client, environmentId) {
86	  const { items } = await client.locale.getMany({ environmentId, query: { limit: 100 } });
87	  return items.map((l) => l.code);
88	}
