25	
26	// Matches the ZimmDrawer slide-in animation duration so focus/modal calls land after the
27	// panel is visible and Chakra's FocusLock has initialised.
28	const DRAWER_ANIMATION_DELAY_MS = 150;
29	
30	// Social IDP sign-in triggers a full-page redirect — onAuthSuccess never fires. Persist a
31	// flag before the redirect so the pending wishlist action can be replayed on return.
32	const PENDING_WISHLIST_INTENT_KEY = 'zimmPendingWishlistAction';
33	
34	const messages = defineMessages({
35	  drawerTitle: {
36	    id: 'wishlist.auth.drawer.title',
37	    defaultMessage: 'Wishlist',
38	  },
39	});
40	
41	const WISHLIST_DESCRIPTION = 'You must log in or create an account to add items to your wishlist.';
42	
43	type UseWishlistAuthDrawerParams = {
44	  onAuthSuccess?: () => void;
45	};
46	
47	export type UseWishlistAuthDrawerReturn = {
48	  isOpen: boolean;
49	  handleDrawerClose: () => void;
50	  handleTriggerClick: (e: SyntheticEvent<HTMLElement>) => void;
51	  /** Ref pointing at the trigger element; passed to ZimmDrawer's finalFocusRef for AC10 focus-return. */
52	  triggerRef: RefObject<HTMLElement>;
53	  drawerTitle: string;
54	  description: string;
55	  emailValue: string;
56	  onEmailChange: (val: string) => void;
57	  onSendCode: () => Promise<{ success: boolean; error?: string } | void>;
58	  onSignInWithApple?: () => void;
59	  onSignInWithGoogle?: () => void;
60	  isSocialEnabled: boolean;
61	  /** Whether the passwordless email login flow is available per site config. */
62	  isPasswordlessEnabled: boolean;
63	  emailInputRef: RefObject<HTMLInputElement>;
64	  /** Error message from a failed social IDP sign-in attempt; absent when no failure has occurred. */
65	  socialError?: string;
66	  onCreateAccount: () => void;
67	  isOtpAuthOpen: boolean;
68	  onOtpAuthClose: () => void;
69	  form: UseFormReturn<FieldValues>;
70	  handlePasswordlessLogin: (email: string) => Promise<{ success: boolean; error?: string }>;
71	  handleOtpVerification: (pwdlessLoginToken: string) => Promise<{ success: boolean; error?: string }>;
72	  registerModal: ReturnType<typeof useAuthModal>;
73	};
74	
75	/**
76	 * Hook — owns all auth-gate state and SFCC SDK integration for the wishlist auth drawer.
77	 * Extracted from `ZimmWishlistAuthDrawer` so that component stays purely presentational.
78	 * Mirrors the same pattern used by SFCC's own `withRegistration` HOC.
79	 *
80	 * @returns All state and event handlers needed to render and drive the auth gate UI.
81	 */
82	export const useWishlistAuthDrawer = ({
83	  onAuthSuccess,
84	}: UseWishlistAuthDrawerParams): UseWishlistAuthDrawerReturn => {
85	  const { formatMessage } = useIntl();
86	  const { t } = useUiCopy();
87	  const { data: customer } = useCurrentCustomer();
88	  const { isRegistered } = useCustomerType();
89	  const { isOpen, onOpen, onClose } = useDisclosure();
90	  const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false);
91	  const [emailValue, setEmailValue] = useState('');
92	  const [socialError, setSocialError] = useState<string | undefined>();
93	  // react-hook-form instance needed by SFCC's OtpAuth component for its internal field registration
94	  const form = useForm();
95	  // Points at the email input so Chakra's Drawer focuses it (not the close button) on open.
96	  const emailInputRef = useRef<HTMLInputElement>(null);
97	
98	  // AC10 focus-return: capture the clicked/focused trigger element at click time.
99	  // React.cloneElement ref forwarding only works if the child uses forwardRef — not
100	  // guaranteed for all consumers. document.activeElement at onClick time is always the
101	  // element that was interacted with, regardless of how the child is implemented.
102	  // Typed as HTMLElement (not HTMLElement | null) to satisfy ZimmDrawer's finalFocusRef prop.
103	  const triggerRef = useRef<HTMLElement>(null as unknown as HTMLElement);
104	
105	  const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless);
106	  const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser);
107	  const authorizeIDP = useAuthHelper(AuthHelpers.AuthorizeIDP);
108	  // SFCC out-of-the-box registration modal — opened when the user clicks "Create an account"
109	  const registerModal = useAuthModal(REGISTER_VIEW);
110	  const { locale } = useMultiSite();
111	
112	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
113	  const loginConfig = (getConfig().app.login || {}) as any;
114	  const passwordlessConfig = loginConfig.passwordless;
115	  const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI);
116	  const isSocialEnabled = !!loginConfig.social?.enabled;
117	  const idps: string[] = loginConfig.social?.idps ?? [];
118	  const socialRedirectPath: string = loginConfig.social?.redirectURI ?? '';
119	  const isPasswordlessEnabled = !!passwordlessConfig?.enabled;
120	
121	  // Move focus to the email input once the drawer's enter animation completes.
122	  useEffect(() => {
123	    if (!isOpen) return;
124	    const timer = setTimeout(() => emailInputRef.current?.focus(), DRAWER_ANIMATION_DELAY_MS);
125	    return () => clearTimeout(timer);
126	  }, [isOpen]);
127	
128	  // When the customer transitions to registered while the drawer (or OTP modal) is open,
129	  // close everything and fire the deferred action.
130	  useEffect(() => {
131	    if (isRegistered && (isOpen || isOtpAuthOpen)) {
132	      onClose();
133	      setIsOtpAuthOpen(false);
134	      onAuthSuccess?.();
135	    }
136	  }, [isRegistered]);
137	
138	  // Social IDP sign-in redirects the page — the drawer closes and onAuthSuccess never fires.
139	  // On mount, if the shopper is already registered and a pending intent was stored before the
140	  // redirect, consume it immediately and clear the flag so it does not replay on subsequent visits.
141	  // Follows the same [isRegistered]-only dep pattern as the effect above: onAuthSuccess is
142	  // intentionally omitted because the intent fires at most once per redirect cycle, and the flag
143	  // is cleared before any re-render that could change the callback reference.
144	  useEffect(() => {
145	    if (!isRegistered) return;
146	    if (!getSessionJSONItem(PENDING_WISHLIST_INTENT_KEY)) return;
147	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
148	    onAuthSuccess?.();
149	    // eslint-disable-next-line react-hooks/exhaustive-deps
150	  }, [isRegistered]);
151	
152	  const handleDrawerClose = () => {
153	    onClose();
154	    form.reset();
155	    setEmailValue('');
156	  };
157	
158	  const handleTriggerClick = (e: SyntheticEvent<HTMLElement>) => {
159	    // e.currentTarget is always the element the handler is attached to — reliable across
160	    // mouse and keyboard, unlike document.activeElement which may still be body on click.
161	    triggerRef.current = e.currentTarget;
162	    if (customer?.isRegistered) {
163	      onAuthSuccess?.();
164	    } else {
165	      onOpen();
166	    }
167	  };
168	
169	  const handlePasswordlessLogin = async (email: string) => {
170	    try {
171	      const redirectPath = window.location.pathname + (window.location.search ?? '');
172	      await authorizePasswordlessLogin.mutateAsync({
173	        userid: email,
174	        mode: passwordlessConfig?.mode,
175	        locale: locale.id,
176	        ...(callbackURL && {
177	          callbackURI: (() => {
178	            const url = new URL(callbackURL);
179	            url.searchParams.set('redirectUrl', redirectPath);
180	            return url.toString();
181	          })(),
182	        }),
183	      });
184	      return { success: true };
185	    } catch (error) {
186	      return {
187	        success: false,
188	        error: formatMessage(getAuthorizePasswordlessErrorMessage((error as Error).message)),
189	      };
190	    }
191	  };
192	
193	  const handleOtpVerification = async (pwdlessLoginToken: string) => {
194	    try {
195	      await loginPasswordless.mutateAsync({ pwdlessLoginToken });
196	      return { success: true };
197	    } catch (e) {
198	      const errorData = await (e as { response?: { json: () => Promise<{ message: string }> } }).response?.json();
199	      return { success: false, error: formatMessage(getLoginPasswordlessErrorMessage(errorData?.message)) };
200	    }
201	  };
202	
203	  const onSendCode = async () => {
204	    if (!isPasswordlessEnabled) return;
205	    const result = await handlePasswordlessLogin(emailValue);
206	    if (result.success) {
207	      onClose();
208	      // Brief delay lets the drawer finish its exit transition before OTP modal mounts.
209	      setTimeout(() => setIsOtpAuthOpen(true), DRAWER_ANIMATION_DELAY_MS);
210	    }
211	    return result;
212	  };
213	
214	  const onSignInWithApple =
215	    isSocialEnabled && idps.includes('apple')
216	      ? async () => {
217	          setSocialError(undefined);
218	          try {
219	            setSessionJSONItem('returnToPage', window.location.pathname);
220	            // Persist the wishlist intent before the redirect — the page reloads after social
221	            // auth completes and onAuthSuccess would otherwise never fire.
222	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, true);
223	            await authorizeIDP.mutateAsync({
224	              hint: 'apple',
225	              // Social IDP redirects are browser-only — window.location.origin is always available
226	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
227	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
228	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
229	            });
230	          } catch {
231	            setSocialError(formatMessage(API_ERROR_MESSAGE));
232	          }
233	        }
234	      : undefined;
235	
236	  const onSignInWithGoogle =
237	    isSocialEnabled && idps.includes('google')
238	      ? async () => {
239	          setSocialError(undefined);
240	          try {
241	            setSessionJSONItem('returnToPage', window.location.pathname);
242	            // Persist the wishlist intent before the redirect — same reason as Apple above.
243	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, true);
244	            await authorizeIDP.mutateAsync({
245	              hint: 'google',
246	              // Social IDP redirects are browser-only — window.location.origin is always available
247	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
248	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
249	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
250	            });
251	          } catch {
252	            setSocialError(formatMessage(API_ERROR_MESSAGE));
253	          }
254	        }
255	      : undefined;
256	
257	  const onCreateAccount = () => {
258	    handleDrawerClose();
259	    registerModal.onOpen();
260	  };
261	
262	  return {
263	    isOpen,
264	    handleDrawerClose,
265	    handleTriggerClick,
266	    triggerRef,
267	    drawerTitle: formatMessage(messages.drawerTitle),
268	    description: t('login.drawer.wishlist.description', WISHLIST_DESCRIPTION),
269	    emailValue,
270	    onEmailChange: setEmailValue,
271	    onSendCode,
272	    onSignInWithApple,
273	    onSignInWithGoogle,
274	    isSocialEnabled,
275	    isPasswordlessEnabled,
276	    emailInputRef,
277	    socialError,
278	    onCreateAccount,
279	    isOtpAuthOpen,
280	    onOtpAuthClose: () => setIsOtpAuthOpen(false),
281	    form,
282	    handlePasswordlessLogin,
283	    handleOtpVerification,
284	    registerModal,
285	  };
286	};
